// Rentenbeiträge – Entscheidung einer Person: { id, decision: valider | revue | refuser, motif }.
// Die Pflegekraft wird hier NICHT gelesen: Sie stammt aus der Sitzung (Knoten « Sitzung »), nie aus dem Inhalt der Anfrage.
const e = $input.first().json?.body ?? {};
const id = String(e.id ?? '');
if (!/^[a-z0-9][a-z0-9-]{2,63}$/.test(id)) throw new Error('Ungültige Akten-ID');
const decision = String(e.decision ?? '');
if (!['valider', 'revue', 'refuser'].includes(decision)) throw new Error('Unbekannte Entscheidung');
return [{ json: { id, decision, motif: String(e.motif ?? '').trim().slice(0, 500) } }];

// Rentenbeiträge – ist die Entscheidung zulässig? Die Regeln werden im GESPEICHERTEN Ergebnis gelesen, nie in der Anfrage.
//   valider : nur wenn die Akte « bereit zur Bestätigung » ist (pret_a_valider) UND alle Regeln (und Abweichungen) « ok » sind
//   refuser : nur nach einer Ausnahme und mit einem Grund
//   revue   : eine Prüfaufgabe, nur einmal
const d = $('Entscheidung prüfen').first().json;
const r = $input.first().json ?? {};
const refus = (erreur, message) => [{ json: { ok: false, reponse: { ok: false, erreur, message } } }];
if (!r.id) return refus('inconnu', 'Unbekannte Akte.');
if (r.traite !== true || !['pret_a_valider', 'exception'].includes(r.statut)) return refus('pas_en_attente', 'Die Akte wartet nicht auf eine Entscheidung (vom Agenten bearbeitet, weder bestätigt noch abgelehnt).');
if (d.decision === 'valider' && (r.statut !== 'pret_a_valider' || r.regles_ok !== true)) return refus('regle_non_ok', 'Bestätigung abgelehnt: Eine Regel ist nicht « ok ».');
if (d.decision === 'refuser' && d.motif === '') return refus('motif_obligatoire', 'Der Ablehnungsgrund ist ein Pflichtfeld.');
if (d.decision === 'refuser' && r.statut !== 'exception') return refus('refus_hors_exception', 'Eine Ablehnung ist nur nach einer Ausnahme möglich.');
if (d.decision === 'revue' && r.revue === true) return refus('revue_deja_creee', 'Für diese Akte besteht bereits eine Prüfaufgabe.');
return [{ json: { ok: true, id: d.id, decision: d.decision, motif: d.motif, soignant: $('Sitzung').first().json.soignant.identifiant } }];

// Rentenbeiträge – Antwort auf die Entscheidung.
const r = $input.first().json ?? {};
if (!r.statut) return [{ json: { ok: false, erreur: 'conflit', message: 'Die Akte wartet nicht mehr auf eine Entscheidung.' } }];
return [{ json: { ok: true, statut: r.statut, revue: r.revue === true } }];

// Sitzungsprüfung – das « Bearer »-Token im Authorization-Header (43 URL-sichere Zeichen) wird gehasht (SHA-256): Nur der Hash steht in der Datenbank.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Sitzungsprüfung – Ergebnis: eine identifizierte Pflegekraft (Sitzung offen, nicht abgelaufen, Konto aktiv) oder nichts.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
